"""随影 TRACE · ModelScope Gradio entry.

One file so the studio root only needs this app.py replaced.
Everec web apps, the StoryLens generator, and the CinePath highlight
are packed inside and shown in tabs. The flight comparer stays live.
"""

from __future__ import annotations

import base64
import gzip
import json
from math import sqrt

import numpy as np
from PIL import Image, ImageDraw

PAYLOAD = ""

HIST_H, HIST_S, HIST_V = 16, 4, 4
HIST_SIZE = HIST_H * HIST_S * HIST_V
MATCH_THRESHOLD = 0.85
COMPOSITION_DELTA = 0.05

SHOTS = {
    "shot_01 Establishing · 建筑建立": (0.50, 0.48, 0.22),
    "shot_02 Follow · 人物跟拍": (0.33, 0.52, 0.31),
    "shot_03 Reveal · 人物揭示": (0.38, 0.50, 0.28),
}


def pages() -> dict[str, str]:
    raw = gzip.decompress(base64.b64decode(PAYLOAD))
    return json.loads(raw.decode("utf-8"))


def frame_for(html: str, height: int = 860) -> str:
    escaped = html.replace("&", "&amp;").replace('"', "&quot;")
    return (
        f'<iframe srcdoc="{escaped}" '
        f'style="width:100%;height:{height}px;border:0;background:#111"></iframe>'
    )


def _as_rgb(image) -> np.ndarray:
    if image is None:
        raise ValueError("请上传图片")
    if isinstance(image, Image.Image):
        array = np.asarray(image.convert("RGB"))
    else:
        array = np.asarray(image)
        if array.ndim == 2:
            array = np.stack([array, array, array], axis=-1)
        if array.shape[-1] == 4:
            array = array[:, :, :3]
    if array.dtype != np.uint8:
        array = np.clip(array, 0, 255).astype(np.uint8)
    return array


def _histogram(image: np.ndarray) -> np.ndarray:
    step = 2
    pixels = image[::step, ::step].reshape(-1, 3).astype(np.float32) / 255.0
    red, green, blue = pixels[:, 0], pixels[:, 1], pixels[:, 2]
    mx = np.maximum(np.maximum(red, green), blue)
    mn = np.minimum(np.minimum(red, green), blue)
    diff = mx - mn
    hue = np.zeros_like(mx)
    mask = diff > 0
    rmax = mask & (mx == red)
    gmax = mask & (mx == green) & ~rmax
    bmax = mask & ~rmax & ~gmax
    hue[rmax] = (60.0 * ((green[rmax] - blue[rmax]) / diff[rmax]) + 360.0) % 360.0
    hue[gmax] = 60.0 * ((blue[gmax] - red[gmax]) / diff[gmax]) + 120.0
    hue[bmax] = 60.0 * ((red[bmax] - green[bmax]) / diff[bmax]) + 240.0
    sat = np.zeros_like(mx)
    sat[mx > 0] = diff[mx > 0] / mx[mx > 0]
    h_bin = np.minimum(HIST_H - 1, (hue / 360.0 * HIST_H).astype(np.int32))
    s_bin = np.minimum(HIST_S - 1, (sat * HIST_S).astype(np.int32))
    v_bin = np.minimum(HIST_V - 1, (mx * HIST_V).astype(np.int32))
    index = (h_bin * HIST_S + s_bin) * HIST_V + v_bin
    bins = np.bincount(index, minlength=HIST_SIZE).astype(np.float64)
    total = bins.sum()
    if total:
        bins /= total
    return bins


def _correlation(left: np.ndarray, right: np.ndarray) -> float:
    da = left - left.mean()
    db = right - right.mean()
    denom = sqrt(float(np.dot(da, da) * np.dot(db, db)))
    if denom == 0:
        return 1.0
    corr = float(np.dot(da, db) / denom)
    return (max(-1.0, min(1.0, corr)) + 1.0) / 2.0


def _parse_box(text: str, width: int, height: int) -> tuple[float, float, float, float]:
    raw = (text or "").strip().replace("，", ",")
    if not raw:
        return (0.42, 0.27, 0.16, 0.46)
    parts = [float(item) for item in raw.split(",")]
    if len(parts) != 4:
        raise ValueError("主体框写成 x,y,w,h，四个 0 到 1 的数")
    x, y, w, h = parts
    if max(x, y, w, h) > 1.5:
        x, y, w, h = x / width, y / height, w / width, h / height
    return x, y, w, h


def _draw(image: np.ndarray, box: tuple[float, float, float, float], target: tuple[float, float]) -> Image.Image:
    canvas = Image.fromarray(image.copy())
    draw = ImageDraw.Draw(canvas)
    width, height = canvas.size
    x, y, w, h = box
    draw.rectangle(
        [x * width, y * height, (x + w) * width, (y + h) * height],
        outline=(230, 194, 122),
        width=3,
    )
    tx, ty = target
    radius = 6
    draw.ellipse(
        [tx * width - radius, ty * height - radius, tx * width + radius, ty * height + radius],
        outline=(244, 239, 228),
        width=3,
    )
    return canvas


def compare(reference, live, shot_name: str, box_text: str):
    ref = _as_rgb(reference)
    frame = _as_rgb(live)
    target_x, target_y, target_area = SHOTS[shot_name]
    box = _parse_box(box_text, frame.shape[1], frame.shape[0])
    x, y, w, h = box
    center = (x + w / 2.0, y + h / 2.0)
    area = max(0.0, w * h)
    hist = _correlation(_histogram(frame), _histogram(ref))
    comp_dist = sqrt((center[0] - target_x) ** 2 + (center[1] - target_y) ** 2 + (area - target_area) ** 2)
    comp = max(0.0, 1.0 - comp_dist / 1.2)
    similarity = 0.6 * hist + 0.4 * comp
    dx = center[0] - target_x
    dy = center[1] - target_y
    composition_ok = abs(dx) <= COMPOSITION_DELTA and abs(dy) <= COMPOSITION_DELTA
    decision = "单帧已接近计划镜头" if similarity >= MATCH_THRESHOLD and composition_ok else "CONTINUE_FOLLOW"
    marked = _draw(frame, box, (target_x, target_y))
    report = "\n".join(
        [
            f"镜头 {shot_name}",
            f"相似度 {similarity:.3f}（直方图 {hist:.3f}，构图 {comp:.3f}，阈值 {MATCH_THRESHOLD:.2f}）",
            f"偏移 dx={dx:+.3f}  dy={dy:+.3f}",
            f"COMPOSITION_OK={composition_ok}",
            f"判定 {decision}",
            "黄框是主体框，圆点是计划分镜的构图目标。连续 8 帧稳定后，PC 端才给出 CAPTURE_GO。",
            "这一页在本机完成比对，不把画面发到其他服务。",
        ]
    )
    return marked, report


OVERVIEW = """# 随影 TRACE

《随影 TRACE》是一套帮助视频创作者轻装上阵、随拍即时成片的软硬件协同系统。它针对拍摄里常见的落差：预期和实拍对不上，现场协调难、成本高，成片质量过度依赖使用者和摄影师的现场理解。

软件分成三块。

- **创作模块**：上传参考，云端大模型辅助创作，输出预设分镜和画面预览；拍摄回传之后做视听再处理和设计。Everec 保留 Simcut 剪辑、Desound 声音、Knowgo 灵感认知、Prerector 协作制片。StoryLens 负责开拍前的分镜界面。
- **空间路径规划**：CinePath 把故事放进空间，生成可预演的摄影路径。这一页放的是《博克图》路径重点。
- **飞行模块**：PC 端用主体框对齐计划分镜。框的格式与 YOLOv8n 的归一化输出一致，低置信度目标在检测阶段丢弃。实时帧和计划分镜的相似度、左右高低偏移在本机计算。当前页面使用 HSV 直方图加构图向量；MobileCLIP2 是同一比对接口上的嵌入替换，这一页没有加载它的权重。

硬件是可拆卸的相机模块，传感器为约 200 万像素的 OV2640，装在可伸缩的模块化无人机上。固件只负责图传。烧录步骤在「硬件」页。

已经落地的是硬件采集、分立的创作模块、路径规划和视觉比对。接下来会继续收紧自动路径和飞行控制，迭代外观，提高图传像素并降低延迟，并探索太阳能储能。
"""

HARDWARE = """# 硬件与烧录

相机模块可以单独取下：AI-Thinker ESP32-CAM 加 OV2640。OV2640 约 200 万像素。模块只出 JPEG，人物框和分镜比对在 PC 上完成，不改无人机原来的电机、电调和飞控。

现行固件默认 VGA（640×480），保证无线图传稳定。传感器仍是约 200 万像素。

## 供电

```
锂电池 → DC-DC 降压 → 5V → ESP32-CAM 的 5V 脚
```

不要把电池直接接到相机板。

## Arduino 烧录

1. 开发板管理器安装 esp32 by Espressif（3.x）。
2. 开发板选择 AI Thinker ESP32-CAM，打开 PSRAM。
3. 打开 `esp32cam/esp32cam.ino`，文件夹名保持 `esp32cam`。
4. 默认热点：名称 `flyvision-cam`，密码 `flyvision`，图传 `http://192.168.4.1/stream`。
5. USB 转串口接 U0R/U0T。烧录时按住 GPIO0 到 GND，再按复位。完成后松开 GPIO0，再复位一次。

烧录后打开 `http://192.168.4.1/stream`，再在 PC 上把实时帧和 CinePath 导出的镜头做比对。

完整固件在飞行包 `05-firmware/esp32cam`。ESP32-P4 端侧推理是后续方案，这次可烧录的是 ESP32-CAM。外观结构、更高像素图传和太阳能储能还在迭代，不在这个页面里驱动电机。
"""


def build_demo():
    import gradio as gr

    packed = pages()
    with gr.Blocks(title="随影 TRACE") as demo:
        gr.Markdown("随影 TRACE · 创作、路径、飞行、硬件在同一页。用上方标签切换。")
        with gr.Tabs():
            with gr.Tab("总览"):
                gr.Markdown(OVERVIEW)
            with gr.Tab("Everec"):
                gr.Markdown("创作模块后半全部保留：剪辑、声音、视觉灵感、协作制片。四个界面都在下面。")
                with gr.Tabs():
                    for label, key in (
                        ("Simcut 剪辑", "simcut"),
                        ("Desound 声音", "desound"),
                        ("Knowgo 灵感", "knowgo"),
                        ("Prerector 协作", "prerector"),
                    ):
                        with gr.Tab(label):
                            gr.HTML(frame_for(packed[key]))
            with gr.Tab("StoryLens"):
                gr.Markdown("开拍前的分镜界面：描述场景，生成连续画面。云端生图需要在界面里填写代理；没有密钥时仍可走本地预览。")
                gr.HTML(frame_for(packed["storylens"], 980))
            with gr.Tab("CinePath"):
                gr.Markdown("空间路径规划的重点：故事镜头、构图目标和导出给飞行模块的字段。")
                gr.HTML(frame_for(packed["cinepath"], 760))
            with gr.Tab("飞行"):
                gr.Markdown(
                    "PC 端比对实时帧和计划分镜。主体框用 YOLOv8n 的归一化格式 `x,y,w,h`，置信度不够的目标在检测时丢掉。相似度在本机计算。"
                )
                with gr.Row():
                    reference = gr.Image(label="计划分镜", type="numpy")
                    live = gr.Image(label="实时帧", type="numpy")
                shot = gr.Dropdown(choices=list(SHOTS), value="shot_03 Reveal · 人物揭示", label="计划镜头")
                box = gr.Textbox(label="主体框 x,y,w,h", value="0.30,0.27,0.16,0.46")
                button = gr.Button("比对")
                marked = gr.Image(label="主体框与构图目标", type="pil")
                report = gr.Textbox(label="偏移反馈", lines=8)
                button.click(compare, [reference, live, shot, box], [marked, report])
            with gr.Tab("硬件"):
                gr.Markdown(HARDWARE)
    return demo


try:
    demo = build_demo()
except ModuleNotFoundError:
    demo = None


if __name__ == "__main__" and demo is not None:
    demo.launch()
